def bulk_update(self, objs, fields, batch_size=None):
    if any(f.primary_key for f in fields):
        raise ValueError('bulk_update() cannot be used with primary key fields.')
    if not objs:
        return 0
    # PK is used twice in the resulting update query, once in the filter
    # and once in the WHEN. Each field will also have one CAST.
    max_batch_size = connections[self.db].ops.bulk_batch_size(['pk', 'pk'] + fields, objs)
    if batch_size is None:
        batch_size = max_batch_size
    elif batch_size > max_batch_size:
        warnings.warn(
            "batch_size was set to %s but the maximum allowed "
            "batch size is %s" % (batch_size, max_batch_size),
            RuntimeWarning,
        )
        batch_size = max_batch_size

    updates = []
    for batch_start in range(0, len(objs), batch_size):
        batch_end = min(batch_start + batch_size, len(objs))
        batch_objs = objs[batch_start:batch_end]
        update_kwargs = {}
        for field in fields:
            case_statement = Case()
            for obj in batch_objs:
                when_clause = When(pk=obj.pk, then=Value(getattr(obj, field.attname)))
                case_statement.add(when_clause, obj.pk)
            if field.null:
                case_statement = Coalesce(case_statement, Value(None))
            else:
                case_statement = Cast(case_statement, output_field=field)
            update_kwargs[field.attname] = case_statement
        updates.append(([obj.pk for obj in batch_objs], update_kwargs))

    rows_updated = 0
    with transaction.atomic(using=self.db, savepoint=False):
        for pks, update_kwargs in updates:
            rows_updated += self.filter(pk__in=pks).update(**update_kwargs)

    return rows_updated
